// Memória feita à mão: as últimas 12 mensagens da conversa entram no pedido para a IA
const ent = $('Chat do cliente').first().json;
let hist = $input.first().json.historico;
if (!Array.isArray(hist)) hist = hist ? [hist] : [];
const linhas = hist.slice(-12).map(s => {
  try { const m = JSON.parse(s); return (m.quem === 'cliente' ? 'Cliente: ' : 'Nina: ') + m.texto; } catch (e) { return ''; }
}).filter(Boolean);
const prompt = (linhas.length ? 'CONVERSA ATÉ AGORA:\n' + linhas.join('\n') + '\n\n' : '') + 'NOVA MENSAGEM DO CLIENTE:\n' + String(ent.chatInput || '').slice(0, 2000);
return [{ json: { prompt } }];

const ent = $('Chat do cliente').first().json;
const resp = String($input.first().json.output || '').trim();
const msgs = [{ quem: 'cliente', texto: String(ent.chatInput || '').slice(0, 2000) }];
if (resp) msgs.push({ quem: 'nina', texto: resp.slice(0, 3000) });
return msgs.map(m => ({ json: { msg: JSON.stringify({ ...m, em: new Date().toISOString() }) } }));

// ⚙️ Configure a loja e a tabela de frete
const LOJA = { nome: 'Empório Natural', lat: -25.4295, lon: -49.2713 };
const TAXA_MINIMA = 5.0;        // vale até KM_INCLUSOS
const KM_INCLUSOS = 2;
const POR_KM_EXTRA = 1.5;
const RAIO_MAXIMO_KM = 15;
const FATOR_RUAS = 1.3;         // a distância em linha reta vezes 1,3 aproxima o caminho pelas ruas

let dados = query;
if (typeof dados === 'string') { try { dados = JSON.parse(dados); } catch (e) { const n = dados.match(/-?\d+(?:\.\d+)?/g) || []; dados = { lat: n[0], lon: n[1] }; } }
const lat = Number(dados && dados.lat), lon = Number(dados && dados.lon);
if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) {
  return 'Coordenadas inválidas. Use antes a ferramenta buscar_coordenadas e envie {"lat": número, "lon": número}.';
}
const rad = g => g * Math.PI / 180;
const R = 6371;
const dLat = rad(lat - LOJA.lat), dLon = rad(lon - LOJA.lon);
const a = Math.sin(dLat / 2) ** 2 + Math.cos(rad(LOJA.lat)) * Math.cos(rad(lat)) * Math.sin(dLon / 2) ** 2;
const linhaReta = 2 * R * Math.asin(Math.sqrt(a));
const km = Math.round(linhaReta * FATOR_RUAS * 10) / 10;
if (km > RAIO_MAXIMO_KM) {
  return JSON.stringify({ entrega: false, distancia_km: km, mensagem: `Fora da área de entrega (atendemos até ${RAIO_MAXIMO_KM} km). O cliente pode retirar na loja.` });
}
const frete = Math.round((TAXA_MINIMA + Math.max(0, km - KM_INCLUSOS) * POR_KM_EXTRA) * 100) / 100;
const minutos = Math.round(20 + km * 3);
return JSON.stringify({ entrega: true, distancia_km: km, frete: frete, frete_texto: 'R$ ' + frete.toFixed(2).replace('.', ','), prazo_estimado: `${minutos} a ${minutos + 15} minutos` });

// ⚙️ Configure a chave Pix da loja (esta é de exemplo, não recebe dinheiro)
const CHAVE = '<SEGREDO_REMOVIDO>';
const NOME = 'Emporio Natural';
const CIDADE = 'Curitiba';

let dados = query;
if (typeof dados === 'string') { try { dados = JSON.parse(dados); } catch (e) { const n = dados.replace(',', '.').match(/\d+(?:\.\d+)?/); dados = { valor: n ? n[0] : 0 }; } }
const valor = Math.round(Number(String(dados && dados.valor).replace(',', '.')) * 100) / 100;
if (!Number.isFinite(valor) || valor <= 0 || valor > 50000) return 'Valor inválido. Envie {"valor": número em reais, "pedido": "identificação opcional"}.';
const txid = String((dados && dados.pedido) || 'PED' + Date.now().toString(36)).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***';

// Pix copia e cola no padrão BR Code do Banco Central (EMV + CRC16)
const emv = (id, v) => { const s = String(v); return id + String(s.length).padStart(2, '0') + s; };
function crc16(s) {
  let c = 0xFFFF;
  for (let i = 0; i < s.length; i++) { c ^= s.charCodeAt(i) << 8; for (let j = 0; j < 8; j++) { c = (c & 0x8000) ? ((c << 1) ^ 0x1021) : (c << 1); c &= 0xFFFF; } }
  return c.toString(16).toUpperCase().padStart(4, '0');
}
const ascii = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase();
let p = emv('00', '01') + emv('26', emv('00', 'br.gov.bcb.pix') + emv('01', CHAVE)) + emv('52', '0000') + emv('53', '986') + emv('54', valor.toFixed(2));
p += emv('58', 'BR') + emv('59', ascii(NOME).slice(0, 25)) + emv('60', ascii(CIDADE).slice(0, 15)) + emv('62', emv('05', txid)) + '6304';
p += crc16(p);
return JSON.stringify({ valor_texto: 'R$ ' + valor.toFixed(2).replace('.', ','), pix_copia_e_cola: p, recebedor: NOME, identificador: txid });

